"use client";

import "./skeleton.css";
import type React from "react";
import { cn } from "tailwind-variants";

import { SkeletonContext, useSkeletonContext } from "./skeleton.context";
import { skeletonVariants, type SkeletonVariants } from "./skeleton.variants";

export type SkeletonProps = SkeletonVariants & React.HTMLAttributes<HTMLDivElement>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonRoot = ({
  children,
  className,
  variant,
  animation,
  shape,
  size,
  ...props
}: SkeletonProps) => {
  const slots = skeletonVariants({ variant, animation, shape, size });

  return (
    <SkeletonContext.Provider value={{ slots }}>
      <div className={cn(slots.root(), className)} {...props}>
        {children}
      </div>
    </SkeletonContext.Provider>
  );
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const Skeleton = SkeletonRoot;

export type SkeletonTextProps = SkeletonProps & {
  lines?: number;
  lastLineWidth?: string;
  gap?: string;
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonText = ({
  lines = 3,
  lastLineWidth = "60%",
  className,
  variant,
  animation,
  shape = "rounded",
  size = "sm",
  ...props
}: SkeletonTextProps) => {
  const { slots } = useSkeletonContext();

  return (
    <div className={cn(slots.text(), className)} {...props}>
      {Array.from({ length: lines }).map((_, index) => (
        <SkeletonRoot
          key={index}
          variant={variant}
          animation={animation}
          shape={shape}
          size={size}
          style={index === lines - 1 && lastLineWidth ? { width: lastLineWidth } : undefined}
          className="w-full"
        />
      ))}
    </div>
  );
};

export type SkeletonAvatarProps = SkeletonProps;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonAvatar = ({
  className,
  variant,
  animation,
  shape = "circle",
  size = "md",
  ...props
}: SkeletonAvatarProps) => {
  const sizeClasses = {
    xs: "h-6 w-6",
    sm: "h-8 w-8",
    md: "h-10 w-10",
    lg: "h-12 w-12",
    xl: "h-16 w-16",
  };

  const chosenSizeClass = sizeClasses[size as keyof typeof sizeClasses] || "h-10 w-10";

  return (
    <SkeletonRoot
      variant={variant}
      animation={animation}
      shape={shape}
      className={cn(chosenSizeClass, "shrink-0", className)}
      {...props}
    />
  );
};

export type SkeletonButtonProps = SkeletonProps;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonButton = ({
  className,
  variant,
  animation,
  shape = "rounded",
  size = "md",
  ...props
}: SkeletonButtonProps) => {
  const sizeClasses = {
    xs: "h-7 w-16",
    sm: "h-8 w-20",
    md: "h-10 w-24",
    lg: "h-11 w-28",
    xl: "h-12 w-32",
  };

  const chosenSizeClass = sizeClasses[size as keyof typeof sizeClasses] || "h-10 w-24";

  return (
    <SkeletonRoot
      variant={variant}
      animation={animation}
      shape={shape}
      className={cn(chosenSizeClass, className)}
      {...props}
    />
  );
};

export type SkeletonCardProps = SkeletonProps;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonCard = ({
  className,
  variant,
  animation,
  shape,
  ...props
}: SkeletonCardProps) => {
  const { slots } = useSkeletonContext();

  return (
    <div className={cn(slots.card(), className)} {...props}>
      <div className="flex items-center gap-3">
        <SkeletonAvatar variant={variant} animation={animation} shape={shape} size="md" />
        <div className="flex-1 space-y-2">
          <SkeletonRoot
            variant={variant}
            animation={animation}
            shape={shape}
            size="sm"
            className="w-1/2"
          />
          <SkeletonRoot
            variant={variant}
            animation={animation}
            shape={shape}
            size="xs"
            className="w-1/3"
          />
        </div>
      </div>
      <SkeletonRoot
        variant={variant}
        animation={animation}
        shape={shape}
        className="h-32 w-full rounded-lg"
      />
      <SkeletonText
        variant={variant}
        animation={animation}
        shape={shape}
        lines={2}
        lastLineWidth="80%"
      />
    </div>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const skeletonVariants = tv({
  slots: {
    root: "skeleton",
    text: "skeleton__text",
    avatar: "skeleton__avatar",
    button: "skeleton__button",
    card: "skeleton__card",
  },
  variants: {
    variant: {
      default: {
        root: "skeleton--default",
      },
      secondary: {
        root: "skeleton--secondary",
      },
      primary: {
        root: "skeleton--primary",
      },
    },
    animation: {
      pulse: {
        root: "skeleton--pulse",
      },
      shimmer: {
        root: "skeleton--shimmer",
      },
      none: {
        root: "skeleton--none",
      },
    },
    shape: {
      rounded: {
        root: "skeleton--rounded",
      },
      circle: {
        root: "skeleton--circle",
      },
      square: {
        root: "skeleton--square",
      },
      pill: {
        root: "skeleton--pill",
      },
    },
    size: {
      xs: {
        root: "skeleton--xs",
      },
      sm: {
        root: "skeleton--sm",
      },
      md: {
        root: "skeleton--md",
      },
      lg: {
        root: "skeleton--lg",
      },
      xl: {
        root: "skeleton--xl",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    animation: "pulse",
    shape: "rounded",
    size: "md",
  },
});

export type SkeletonVariants = VariantProps<typeof skeletonVariants>;

"use client";

import { createContext, useContext } from "react";

import { skeletonVariants } from "./skeleton.variants";

export type SkeletonContext = {
  slots: ReturnType<typeof skeletonVariants>;
};

export const SkeletonContext = createContext<SkeletonContext | null>(null);

export const useSkeletonContext = () => {
  const context = useContext(SkeletonContext);
  return context ?? { slots: skeletonVariants() };
};

.skeleton {
  @apply bg-muted relative overflow-hidden select-none;
}

.skeleton--default {
  @apply bg-muted;
}

.skeleton--secondary {
  @apply bg-muted/60;
}

.skeleton--primary {
  @apply bg-primary/10;
}

/* Animations */
.skeleton--pulse {
  @apply animate-pulse;
}

.skeleton--shimmer {
  @apply relative overflow-hidden;
}

.skeleton--shimmer::after {
  content: "";
  @apply absolute inset-0 -translate-x-full;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.2) 20%,
    rgba(255, 255, 255, 0.4) 50%,
    rgba(255, 255, 255, 0.2) 80%,
    transparent 100%
  );
  animation: skeleton-shimmer 2s infinite;
}

:root.dark .skeleton--shimmer::after,
.dark .skeleton--shimmer::after {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.03) 20%,
    rgba(255, 255, 255, 0.08) 50%,
    rgba(255, 255, 255, 0.03) 80%,
    transparent 100%
  );
}

@keyframes skeleton-shimmer {
  100% {
    transform: translateX(100%);
  }
}

.skeleton--none {
  animation: none;
}

/* Shapes */
.skeleton--rounded {
  @apply rounded-md;
}

.skeleton--circle {
  @apply rounded-full;
}

.skeleton--square {
  @apply rounded-none;
}

.skeleton--pill {
  @apply rounded-full;
}

/* Sizes */
.skeleton--xs {
  @apply h-3;
}

.skeleton--sm {
  @apply h-4;
}

.skeleton--md {
  @apply h-6;
}

.skeleton--lg {
  @apply h-8;
}

.skeleton--xl {
  @apply h-12;
}

.skeleton__text {
  @apply flex flex-col gap-2;
}

.skeleton__avatar {
  @apply shrink-0;
}

.skeleton__button {
  @apply inline-block;
}

.skeleton__card {
  @apply border-border bg-card flex flex-col gap-4 rounded-xl border p-4 shadow-xs;
}

import {
  Skeleton,
  SkeletonAvatar,
  SkeletonButton,
  SkeletonCard,
  SkeletonRoot,
  SkeletonText,
} from "./skeleton";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/skeleton/content.md
 */
export const SkeletonContainer = {
  Avatar: SkeletonAvatar,
  Button: SkeletonButton,
  Card: SkeletonCard,
  Root: SkeletonRoot,
  Text: SkeletonText,
};

export { Skeleton, SkeletonAvatar, SkeletonButton, SkeletonCard, SkeletonRoot, SkeletonText };

export type {
  SkeletonAvatarProps,
  SkeletonButtonProps,
  SkeletonCardProps,
  SkeletonProps,
  SkeletonTextProps,
} from "./skeleton";

export { SkeletonContext, useSkeletonContext } from "./skeleton.context";
export { type SkeletonVariants, skeletonVariants } from "./skeleton.variants";
